/* Evolvlings: English text for the era 5 path conversations (parallel to events-era5.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: the granary, Lirio and Moho, the rations and the Frozen Tomb ==================== */

  add("deep", {
    "e5-granero": { who: { centeno: "Centeno, granary steward" }, nodes: {
      a: { say: ["At the entrance to the White Deep there is a queue that runs down the slope and disappears into the snow. Folk from the Meadow, the Forest, the Heights. Some have been waiting for days. Their faces are burnt by the cold.",
                 "Inside, in a hall of blue ice, sacks are stacked to the ceiling. The ice on the walls doesn't drip: it's root ice, which never melts. Food kept here doesn't rot.",
                 "I'm Centeno. I'm from the Forest, but the regent put me in charge of handing out because I can count and I'm not from here. That way nobody says the Deep hands out for the Deep.",
                 "One sack per family per week. If it stretches. This month it doesn't stretch."],
           opts: ["“How much food is left?”", "“When the Bell rang, did anyone know this would happen?”", "“Without furnaces, the Glade had no way to keep warm.”", "“With a forge for every people, the cold rose everywhere.”", "Help him hand out", "Join the queue, like everyone else"] },
      cuanta: { say: ["Enough for two winters, if nobody else comes. A hundred families come every week.",
                      "And root ice isn't endless. Every time a block is cut for a new hall, the Deep gets a little colder. The old folk say the whole Glade does."] },
      campana: { say: ["Nobody. It rang, the Root went to sleep and everyone celebrated. The next day it snowed. It was early for snow. Nobody thought anything of it.",
                       "My grandmother says that night's snow is still under the snow that fell yesterday. It never went away."] },
      ascuas: { say: ["There weren't any. Hands stopped turning to stone, that much is true. But when the cold came, people burnt their chairs, then their doors, then their beams.",
                      "Now they burn the Forest's trees. My Forest. That's why I'm here: so my family eats without having to cut."] },
      forja: { say: ["Slowly. A small forge doesn't warm a village. The Root cooled everywhere at once, and the cold rose the way water rises in a well.",
                     "Nobody was to blame alone. That's the worst part: there's nobody to shout at."] },
      ayudar: { say: ["You spend the day passing sacks from hand to hand. Centeno writes each one down on a wooden tablet. His nails are black with ink.",
                      "At the end of the day, the queue is no shorter. More people arrived than left.",
                      "Every day it's like this. It never ends. But today forty more families ate than yesterday, because there were two of us."] },
      fila: { say: ["You go to the end of the queue. In front of you is a woman from the Meadow with two children asleep in a blanket.",
                    "It takes you half a day to reach the front. When you get there, Centeno recognises you and gives you an odd look.",
                    "You, in the queue? Well. Now you know how long it takes. Hardly anyone who makes the decisions knows."] },
    } },

    "e5-lirio": { who: { lirio: "Lirio, of the House of Ice" }, nodes: {
      a: { say: ["In an ice corridor of the Deep, a young woman with white-braided hair and a House of Ice coat counts jars of preserves on a shelf. She does it fast, out loud, without a single mistake.",
                 "When a guard walks by, she straightens up and salutes. When the guard turns the corner, she leans on the shelf and takes a deep breath.",
                 "My name is Lirio. You're the one who keeps watch at the Ford. My mother says you're the only person in the Glade who owes nothing to the Deep. Is that true?"],
           opts: ["“Why do you ask?”", "“You look tired of doing everything right.”", "“Is there someone you want to see and can't?”"] },
      porque: { say: ["Because I need someone who owes nothing to the Deep. So nobody can tell them no.",
                      "But not here. Here the walls are ice and ice hears everything. That's what the old folk say. I think what hears everything is the guard."] },
      bien: { say: ["Tired. Yes. In the House of Ice everything is done right. You count right, you salute right, you marry right.",
                    "Her voice cracks on the last word. She covers it with a cough.",
                    "Sorry. It's cold. It's always cold."] },
      alguien: { say: ["Lirio looks at you for a long time. Then she looks at the corner where the guard went.",
                       "There's a boy. From the House of the Mushroom. His name is Moho. He laughs at everything, even the law. I don't laugh at anything.",
                       "There's an old law, the second statue's, that says Ice and Mushroom don't marry. Nobody knows why. But everyone keeps it. I keep it. As long as someone is watching."] },
    } },

    "e5-moho": { who: { moho: "Moho, of the House of the Mushroom" }, nodes: {
      a: { say: ["In the greenhouses of the House of the Mushroom, under the Deep, it's warm and damp. Mushrooms grow on wooden shelves, white and huge. A skinny young man waters them while singing a rude song about the regent.",
                 "A visitor! Come in, come in. Down here is the only place in the Deep where you can sweat. My name is Moho. I water, I sing, and I make fun of the law. I do all three badly.",
                 "They say you knew my great-grandmother, or my great-grandmother's grandmother. In the House of the Mushroom people live long and count strangely. Esporina, her name is. She's still alive. She's older than the Deep."],
           opts: ["“What do you laugh at so much?”", "“Lirio told me about you.”", "“Are you afraid of the law?”"] },
      rie: { say: ["At everything that scares me. If I laugh, it doesn't show. The regent scares me, so I have ten songs about her.",
                   "The law scares me, so I have twenty. Winter scares me, so I laugh at the snow. I'm a bit tired of it, honestly."] },
      lirio: { say: ["Moho stops watering. For the first time, he isn't smiling.",
                     "She told you? Her? About me?",
                     "Then it's true. I thought I'd dreamt it. Mushrooms make you dream things. But I didn't dream this.",
                     "He goes back to watering, slowly. His hands shake a little. He doesn't sing."] },
      miedo: { say: ["Afraid? No. Well. Yes.",
                     "He sits on an upturned crate. He takes off his mushroom cap.",
                     "My great-grandmother loved someone from the Ice, long ago. She obeyed the law. She never forgave herself. I don't want to obey. But I don't want Lirio thrown out of her House because of me either."] },
    } },

    "e5-esporina": { who: { esporina: "Esporina" }, nodes: {
      a: { say: ["In the deepest greenhouse of the House of the Mushroom, sitting among mushrooms as tall as trees, there is a woman so old her skin looks like bark. She wears a mushroom hat full of notes on the inside.",
                 "Caretaker. I'm Esporina. The years don't touch you. They touch me. You watched me grow old. We're even.",
                 "My grandson Moho, the one who laughs, loves the Ice girl. I know. I know because I did the same. And I don't want him to do what I did next."],
           opts: ["“What did you do next?”", "“Why does that law exist?”", "“Tell Moho. Now, don't wait.”", "“That's their business, not yours.”"] },
      despues: { say: ["I obeyed. He was from the Ice. His name was Nevado. He kept the Watch. We met in the dreamers' hall, because everyone there is asleep and nobody looks.",
                       "When it came out, they told me to choose: the House or him. I chose the House. He kept the Watch until he died. I kept watering mushrooms. A hundred and twenty years watering mushrooms."] },
      ley: { say: ["Nobody knows. I don't either. It's written on the base of the second statue in the Heart, the one with two figures holding hands.",
                   "The strange thing is that the statue shows Ice and Mushroom together. And the law says they must not come together. Someone read the statue backwards. Or someone read it right and got scared."] },
      decir: { say: ["Now. Yes. I always say things late. When the truth is no use to anyone.",
                     "She gets up with a root cane. It takes her a long time to climb the greenhouse stairs. She won't take your arm.",
                     "That night, Moho and Esporina talk until morning. When Moho comes out, his eyes are red and he doesn't laugh at anything all day.",
                     "I told him everything. What I did, what I lost, what still hurts. I don't know if I helped him or scared him. Both, surely."] },
      suyo: { say: ["It's theirs. You're right. And the law belongs to everyone. That's why it weighs so much.",
                    "She looks back at her mushrooms. She doesn't speak to you any more. After a while, without turning round, she says one more thing.",
                    "If you see them together, don't tell anyone. That much is your business."] },
    } },

    "e5-raciones": { who: { cellisca: "Regent Cellisca", centeno: "Centeno, granary steward" }, nodes: {
      a: { say: ["In the throne hall of the Deep, a tall woman with a crown of worked ice reads one of Centeno's tablets. It's Regent Cellisca, granddaughter of Albina's granddaughter. Her hands are crossed over her chest, as if she were cold inside.",
                 "The granary won't reach everyone this winter. Someone has to eat less. The Council wants me to decide who. I want someone from outside to decide, so nobody can say the Deep chose.",
                 "There are three ways, regent. All three are bad.",
                 "You choose, Caretaker. You owe nothing to anyone. If you get it wrong, the blame is yours. If you get it right, the regency gave you its support."],
           opts: ["“Why don't you decide?”", "Share it equally among everyone", "Workers first: those who cut wood and carry sacks", "Children first"] },
      porque: { say: ["Because when people are hungry, they hate whoever hands out. And the regency can't afford to be hated. We're the only thing keeping the granary shut.",
                      "If everyone opens it at once, it's gone in a week. Hunger is an argument, Caretaker. I use it. Don't ask me to like it."] },
      igual: { say: ["Equally. A little for everyone. Nobody dies this week. Everyone is hungry.",
                     "So it's done. The queues get longer, but they move. By the third week, the woodcutters have no strength to cut. There's less wood. It's colder.",
                     "Fair doesn't keep anyone warm. But nobody can say it wasn't fair."] },
      trabajo: { say: ["Workers first. Woodcutters, carriers, ice cutters. If they eat, there's wood and there's food for next month.",
                       "So it's done. The wood comes. The halls warm up. But in the Meadow, where there's no work, families get half a sack. Some old folk stop coming down to the queue.",
                       "It works. Those who eat work, and those who work eat. The others remember. The Meadow will remember for a long time."] },
      ninos: { say: ["Children first. Every child of every people eats a full share. The grown-ups get what's left.",
                     "So it's done. The children stop crying in the queues. The parents eat half, and some less, so the sack lasts.",
                     "In the fourth week, two woodcutters faint in the Forest. One doesn't get up.",
                     "The children will live. Some without a father. That's winter: it doesn't let you choose without charging."] },
    } },

    "e5-amantes": { who: { lirio: "Lirio, of the House of Ice", moho: "Moho, of the House of the Mushroom", cellisca: "Regent Cellisca" }, nodes: {
      a: { say: ["In the Watch hall, among the dreamers sleeping under waxed blankets, two people sit on the floor, awake, holding hands. Lirio and Moho.",
                 "Here everyone sleeps and nobody looks. My great-great-grandmother used to come here, they say. With someone from the Mushroom.",
                 "Mine too. With someone from the Ice. Maybe they were the same two. Maybe the hall is used to it.",
                 "The guard saw us yesterday. She hasn't said anything yet. But she will. You have to help us. Please."],
           opts: ["“What do you want to do?”", "Help them flee through the Mushroom tunnels", "Tell the regent before the guard does", "“Ask for the wedding in public, in front of everyone.”"] },
      querer: { say: ["Get married. Without asking permission. I'd do it tomorrow, at the granary door, with the queue as witness.",
                      "I want my House to accept it. I don't want to run away. I want to walk in through the door with him and have my mother greet him.",
                      "That's not going to happen.",
                      "I know. I want it anyway."] },
      huir: { say: ["Moho knows the Mushroom tunnels better than anyone. That night you guide them to the southern exit, where the tunnels open onto the snow.",
                    "Lirio stops at the exit. She looks back, towards the Deep. Then she looks at Moho.",
                    "If I leave, I'll never belong to my House again. My mother will say I died.",
                    "Then let's go and belong to nobody together. It's cheaper.",
                    "They head for the Ford, through the snow, on foot. The next day, the House of Ice hangs a black cloth on its door."] },
      contar: { say: ["You go to the throne hall. Cellisca listens without moving. At the end, she nods.",
                      "Thank you. If the guard had told me, I'd have had to punish it in public. You told me in private. I can be gentler.",
                      "The next day, Lirio is sent to the Deep's northern border, to tend the blocks of root ice. Moho, to the deepest greenhouses. They can't see each other.",
                      "Gentler. I didn't say kind. I said gentler."] },
      publico: { say: ["In public? In front of everyone?",
                       "Yes! At the granary door! With the queue as witness!",
                       "The next day, Lirio and Moho stand at the granary door, hand in hand, in front of the whole queue. Lirio speaks. Her voice doesn't shake.",
                       "I want to marry Moho, of the House of the Mushroom. I'm asking out loud so everyone hears it. If the law says no, let the law say it in front of you all.",
                       "The queue goes silent. Someone claps. Then another. The guard comes running. She doesn't know whom to take first."] },
    } },

    "e5-hieloraiz": { who: { centeno: "Centeno, granary steward", cellisca: "Regent Cellisca" }, nodes: {
      a: { say: ["At the Deep's border, where the oldest ice begins, a group of cutters waits with bone saws. In front of them is a blue wall so dark it looks black. Root ice.",
                 "If we cut this wall, there's room for twice the food. Nobody goes hungry this winter.",
                 "And the Deep gets twice as cold. The old folk say every block of root ice cut is cold the Root can no longer hold. That the cold gets loose and rises.",
                 "The old folk say lots of things. The queue outside says nothing. It's hungry."],
           opts: ["“Is what the old folk say true?”", "Cut. Let nobody go hungry today.", "Don't cut. The cold is already too much."] },
      verdad: { say: ["Nobody knows. But since the cutting started, winter has been harder. It could be chance. It could be not.",
                      "Since the cutting started, more people eat too. That's no chance."] },
      cortar: { say: ["The bone saws bite into the ice. A white vapour comes out, cold, that burns the skin. The cutters work with their eyes shut.",
                      "In a week there's a new hall, huge. It fills with sacks. The queue outside moves faster.",
                      "That week, the Lake freezes three hands deeper. In the Heights, two villages are buried completely.",
                      "They eat. Today they eat. Tomorrow's for tomorrow."] },
      nocortar: { say: ["The cutters put away their saws. The blue wall stays whole.",
                        "Fine. Then the queue waits longer. And some in the queue won't make it to the door.",
                        "And winter doesn't get worse. At least not because of us. Not much comfort to someone who dies waiting.",
                        "Centeno leaves without saying goodbye. That night, someone leaves a bag of grain at the door of his house in the Forest. Nobody knows where it came from."] },
    } },

    "e5-desvelo": { who: { desvelo: "Desvelo, voice of Those Who Hear" }, nodes: {
      a: { say: ["Before the Frozen Tomb, a man in a grey robe with very wide eyes speaks to a crowd of Day folk. He speaks slowly, in a warm voice. They listen as if he were feeding them.",
                 "The Sleeping King speaks to us. Winter is his message. He tells us to come together, to obey the regency, to wait. That whoever waits, eats.",
                 "The people nod. A woman cries. A child asks when winter will end, and Desvelo strokes his head.",
                 "When the King wakes, little one. When we've been good."],
           opts: ["“Did you really hear the King?”", "“There's no king in the Tomb. There's a root.”", "“Tell them what you know, not what they want to hear.”", "Listen to the end"] },
      oyo: { say: ["I hear what people hear when they're afraid. That there's a meaning. That someone is in charge. That it's not for nothing.",
                   "Whether that's the King or me, I don't know. I don't know any more. I've been saying it for twenty years."] },
      raiz: { say: ["Desvelo looks at you. For a moment, the warm voice leaves him.",
                    "I know. My teacher opened the door once, as a boy, in secret. He saw the tip of the root and the scratches on the inside.",
                    "But if I say that, what are they left with? A root that doesn't hear and a winter that doesn't end? I'd rather give them a king. A king can be waited for."] },
      decir: { say: ["What I know? To them? Now, hungry?",
                     "He looks at the crowd. At the child who asked. At the crying woman.",
                     "Tomorrow. Tomorrow I'll tell them. Today I can't.",
                     "The next day he talks about the King again. But at the end he adds a new sentence, quietly: “And if the King doesn't wake, we may have to do something ourselves.”"] },
      escuchar: { say: ["You stay to the end. Desvelo speaks for an hour. He says the cold purifies, that the regency is just, that the queues are a test.",
                        "When he finishes, the people leave calmer. None of them has more food than before. But they walk upright.",
                        "You see. I gave them nothing. And they leave better than they came. Is that wrong?"] },
    } },
  });

  add("aurora", {
    "e5-faroles": { who: { pavesa: "Pavesa, lamplighter" }, nodes: {
      a: { say: ["The Meadow's streets are empty and white. The lanterns hold their flames inside, still, frozen like a flower in ice. They give light, but no warmth.",
                 "An old lamplighter climbs a ladder and taps a lantern with a small hammer. The glass doesn't break. The flame doesn't move.",
                 "I'm Pavesa. My grandfather was Cerillo, from the Quarter, the one with the chalk squares. I light lanterns that never go out and never warm. It's the most useless job in the Glade."],
           opts: ["“Why did they freeze like that?”", "Help her break a lantern to get the flame out", "“Gather people under the lanterns. Light is something.”"] },
      porque: { say: ["Nobody knows. One night it was so cold the flame went still. It's been like that ever since. It neither goes out nor warms.",
                      "My grandfather used to say the board was missing nights. Now there are too many: they're all the same night."] },
      romper: { say: ["You hit the lantern with the hammer until the glass cracks. The frozen flame falls into your hand. It's as heavy as a stone and cold.",
                      "You put it in a bowl of oil. It lights nothing. But it shines. The street children come to look at it."] },
      juntar: { say: ["Pavesa goes from house to house knocking on doors. At dusk, forty people gather under the biggest lantern in the square, packed tight, with blankets.",
                      "It's no less cold. But among forty bodies, you feel it less. Someone sings. Someone else brings thin soup.",
                      "Light doesn't warm. People do. If the peoples gather in the Heart, the Meadow will go like this: packed tight, with blankets, singing."] },
    } },

    "e5-cola": { who: { pavesa: "Pavesa, lamplighter" }, nodes: {
      a: { say: ["Down the road from the Meadow to the Deep comes a line of sledges pulled by people. They carry old folk, children, things to trade. They're going to the granary. It takes four days.",
                 "Halfway along, a sledge has broken. A family from the Quarter stands at the roadside, in the snow, not knowing what to do. The other sledges pass without stopping.",
                 "If they stop to help, they lose their place in the line. Nobody stops. Simple as that."],
           opts: ["Fix the sledge", "Carry the family on your own sledge", "Ask the passers-by to take turns pulling them"] },
      arreglar: { say: ["You lash the broken runner with rope and a branch. It takes an hour. The line keeps passing.",
                        "When you finish, the family is at the end of the line. They'll arrive a day after everyone else.",
                        "A day. At the granary, a day can mean half a sack less. But they'll get there."] },
      llevar: { say: ["You load the old folk and the children onto your sledge and pull it yourself. The family walks alongside. You reach the Deep four days later, all of you.",
                      "At the granary door, the mother of the family gives you a piece of chalk. It's all she has.",
                      "Chalk. From the Quarter. For drawing squares. My grandfather would be pleased."] },
      turnar: { say: ["You stop the line. You speak up. At first nobody wants to. Then a man from the Heights gets off his sledge and says he'll pull first.",
                      "They take turns. Each sledge pulls the family for a stretch. The line goes slower, but it goes together.",
                      "Slower, together. The Quarter will remember who got off first. When the Heart calls, it'll go in line, taking turns."] },
    } },
  });

  add("crater", {
    "e5-calor": { who: { chispa: "Chispa, smith" }, nodes: {
      a: { say: ["In the Crater there is a queue that goes round the mountain. People from every village wait with a log or a plank under their arm: the price of a night by the fire.",
                 "Inside, around what's left of the furnaces, hundreds of people sleep on the floor, in rows. A grey-haired smith walks among them with a bucket of embers, handing out warmth.",
                 "Caretaker! I'm Chispa, from the south slope. The one with the first nail. I have grandchildren now. And the Crater is the only warm place in the Glade. I never thought I'd miss the smoke."],
           opts: ["“Why do you charge to get in?”", "“How's your hand?”", "“Let in those with no wood. Let those who have it pay.”", "Help her hand out embers"] },
      cobra: { say: ["Because without wood there's no fire. And without fire there's no Crater. They bring the wood. That's fair, the masters say.",
                     "What they don't say is that those with no wood sleep outside. And outside you don't sleep: you wait for morning."] },
      mano: { say: ["Chispa raises her hands and looks at them for a while, as if they belonged to someone else.",
                    "They're the ones Fire left me. I don't complain about them any more. My grandchildren have whole hands. That's what I count."] },
      gratis: { say: ["Free for those who have nothing? The masters will throw me out.",
                      "She looks at the queue. At the end there's an old woman with no log, holding a child by the hand.",
                      "Let them throw me out. Fire learnt to give warmth without charging once. On the Night of Embers, they say. Let it learn again.",
                      "That night Chispa lets in forty people with no wood. The masters shout. She puts a bucket of embers in their hands and tells them to hand out."] },
      brasas: { say: ["You walk among the rows of sleeping people with a bucket of embers. You put a handful beside each family. The embers die fast. You fill the bucket again.",
                      "By dawn your arms are black to the elbow. Chispa gives you a cup of something hot.",
                      "All night. Like me, like my children. Now you know what it is to be Fire in winter."] },
    } },
  });

  add("forest", {
    "e5-robles": { who: { abeto: "Abeto, of the Council" }, nodes: {
      a: { say: ["In the Deep Forest, the oldest oaks have doors. The Council hollowed them out carefully, without killing them, so families can sleep inside. Smoke comes out of the knots in the bark.",
                 "I'm Abeto, of the Council. We hollowed the oaks that were already hollow, or nearly. That way both the tree and the family live. Both cold, but alive.",
                 "The trouble is there are more families than oaks. And those from outside want to cut the oaks for firewood. An oak gives wood for a month. Or a roof for ten years."],
           opts: ["“Who decides who sleeps in the oaks?”", "“Open the oaks to families from outside too.”", "“Give one oak for firewood. Just one.”", "Help hollow another oak"] },
      quien: { say: ["The Council. Forest folk first. Then, if there's room, those from outside.",
                     "There's no room. There's never room. The Council learnt to say no a hundred years ago, and still hasn't learnt anything else."] },
      abrir: { say: ["To outsiders? Meadow folk sleeping in our oaks?",
                     "You remind him of the clearing of stumps, the Forest Mother, three for one. That the Forest survived because someone from outside looked after it.",
                     "Fine. One outside family for each oak, alongside the one inside. They'll be packed in. They'll quarrel. But the Forest will go to the Heart with its doors open."] },
      uno: { say: ["The Council votes. One oak is cut, the sickest. It gives wood for a month to a hundred families.",
                   "One oak. And next month they'll ask for another. It's always one. Until there are none left."] },
      ahuecar: { say: ["You work with Abeto for two days, with gouges and patience, taking the dead wood out of an oak's heart. The living bark must stay, and a finger of healthy wood.",
                       "When you finish, a Forest family moves in with their things. The oak creaks, but holds.",
                       "Ten years of roof. If winter doesn't last longer. If it does, the oak will get tired too."] },
    } },

    "e5-reparto": { who: { centeno: "Centeno, granary steward" }, nodes: {
      a: { say: ["At a house in the Forest, beside a hollow oak, Centeno unloads a sledge at night. He takes three sacks from the granary and puts them in a hole under the floor.",
                 "When he sees you, he freezes with a sack in his arms.",
                 "They're for my mother. And my nephews. Three sacks. Out of two thousand. Nobody will miss them."],
           opts: ["“How many times have you done this?”", "“Take them back to the granary.”", "“Share them among the families in the oaks.”", "Say nothing"] },
      veces: { say: ["Every week. Three sacks. Sometimes four.",
                     "I'm not a thief. I'm the one who hands out. Wouldn't you keep a little for your own, if you had the key?"] },
      devolver: { say: ["Centeno looks at the hole in the floor. He looks at the house, where his mother and three children are sleeping.",
                        "I'll take them back. Tomorrow. And I'll go to the queue with them, like everyone.",
                        "He does. A month later, his mother is thinner. Centeno hands out at the granary with sunken eyes and doesn't keep a single handful."] },
      repartir: { say: ["Among all the families in the oaks? It's three sacks. It's not enough for anything.",
                        "But he does it. Three sacks among forty families. A handful each.",
                        "A handful. Well. Now I'm a thief who hands out. It's strange, but I sleep better."] },
      callar: { say: ["You say nothing. Centeno finishes hiding the sacks and covers the hole with a rug.",
                      "Thank you. I won't forget it. And you won't let me forget it, will you? I know that too."] },
    } },
  });

  add("hollow", {
    "e5-mantas": { who: { tizna: "Tizna, weaver of the Court" }, nodes: {
      a: { say: ["In the Hollow, in a workshop of black looms, a Court weaver works with threads that are hard to see: they move, like the shadows of branches. The blankets coming off the loom are warm to the touch.",
                 "I'm Tizna. I weave shadow blankets. They keep the body's heat in and don't let it out. The Court sells them dear. And rents them dearer still, by the night.",
                 "The bad part is that if you sleep with one too long, the blanket's shadow sticks to you. You get up with a darker shadow. And a heavier one."],
           opts: ["“How many people sleep with these blankets?”", "“Give them to those sleeping outside the Crater.”", "“Warn everyone about the shadow that sticks.”", "Try a blanket"] },
      cuanta: { say: ["Half the Meadow. Those who can pay. Those who can't freeze or go down to the Deep.",
                      "The Court is earning more this winter than in a hundred years. My Queen is happy. I weave and don't think. It's what they ask of me."] },
      regalar: { say: ["Give them away? The Court will hang me from the loom.",
                       "She looks at the stacked blankets. A hundred. Two hundred.",
                       "Twenty. Twenty can get lost in a move. Moves are dangerous in winter, aren't they?",
                       "That night, twenty shadow blankets turn up in the Crater queue, with no note. Twenty families sleep warm."] },
      avisar: { say: ["Tell about the shadow? That the blanket warms and charges?",
                      "She holds a thread between her fingers. The thread winds itself around her wrist.",
                      "Fine. If the Court is going to the Heart, let it go saying what it charges. For once, let the Hollow sell something with the label on.",
                      "The next day, every shadow blanket leaving the workshop has a paper sewn on: “Warms. Weighs. Don't sleep with it more than three nights in a row.”"] },
      probar: { say: ["You wrap yourself in a shadow blanket. The warmth is instant, total, like a hug that never ends. You want to sleep forever.",
                      "You pull it off with an effort. Your shadow, on the wall, takes a second to move when you do.",
                      "See? One night and that's it. Imagine a winter."] },
    } },
  });

  add("lake", {
    "e5-bajohielo": { who: { rada: "Old Rada" }, nodes: {
      a: { say: ["Mirror Lake is frozen from shore to shore. People cross it on foot, in line, to get from the Meadow to the Deep faster. The ice is as clear as glass.",
                 "Things can be seen underneath. A sunken boat. A stone street. A round forge with a red ember still alight. Faces. No: statues. Or not.",
                 "I'm Rada. Old now. I used to read walls with my fingers. Now the lake shows me everything it covered, and I can't touch it. It's like having an open book behind glass."],
           opts: ["“What scares you most to see?”", "Open a hole in the ice to touch something", "“Guide people where the ice is thickest.”"] },
      asusta: { say: ["The faces. There are people under the ice. They froze crossing, this winter and the last. Some still have their eyes open.",
                      "And we Tides cross over them every day, to go and ask for food. Walking on those who didn't make it."] },
      agujero: { say: ["You chip at the ice with a bar until black, freezing water comes up. Rada puts her arm in up to the elbow.",
                       "She pulls out a stone tablet with letters. She touches it with her eyes closed. Her hand turns blue.",
                       "It says: “Cold keeps. Whoever keeps, charges.” Nothing more. Someone from the Deep wrote it, long ago. I can tell by the letters: straight, like ice."] },
      guiar: { say: ["Rada knows the lake better than anyone. She walks ahead of the line, testing the ice with a stick, listening to how it sounds. Where it sounds hollow, she changes course.",
                     "You plant rag flags along the safe path. By the end of the day, there's a line of flags from shore to shore.",
                     "There. Nobody else under the ice for crossing badly. We Tides guide. It's what we did before they gave us houses. If the Heart calls, we'll go like this: ahead, testing."] },
    } },
  });

  add("caves", {
    "e5-entrada": { who: { pizca: "Pizca, of the Hondura" }, nodes: {
      a: { say: ["At the mouth of the Echo Caves there is a new wooden gate with a little window. Warm air comes out from the other side. Outside, cold people wait with coins in their hands.",
                 "A Hondura woman with a dented helmet takes money through the window. Her knees are bandaged, as if they'd been scraped raw since childhood.",
                 "Caretaker! I'm Pizca. The one from the small tunnels. Now I'm the one who charges at the door. One coin a night. Inside you sleep in shifts, in the warm galleries."],
           opts: ["“Why does the Hondura charge?”", "“You know what it is to work in a tunnel with nobody looking after you.”", "“Open the gate tonight. Just one night.”", "Pay the entry for those who have nothing"] },
      cobra: { say: ["Because the Hondura was always the one that digs and stays below. Now everyone wants to be below, because below is warm. For the first time, below is worth something.",
                     "Don't look at me like that. My grandmother pushed buckets for half pay. I charge one coin. It's the first time the Hondura charges instead of paying."] },
      tunel: { say: ["Pizca stops counting coins. She looks at her knees.",
                     "I know. I know better than anyone.",
                     "Fine. Children get in free. All children, from every people. And whoever comes holding a child's hand too. If the Hondura goes to the Heart, let it go with the door open for children."] },
      abrir: { say: ["One night? And if tomorrow nobody wants to pay?",
                     "But she opens the gate. People come in, many, too many. Inside, the galleries fill up. There's shouting, shoving, a child who gets lost and is found at dawn.",
                     "One night. That's it. Tomorrow I charge again. But tonight everyone slept warm. Badly, packed in, but warm."] },
      pagar: { say: ["You give Pizca a handful of coins. She counts them twice, the way they do in the Hondura.",
                     "Twenty nights. I'll share them among those waiting with no coin. What a strange thing, Caretaker. You pay what nobody charges you."] },
    } },
  });

  add("heights", {
    "e5-pasos": { who: { romanza: "Romanza, messenger" }, nodes: {
      a: { say: ["In the Heights, the snow reaches the roofs. The northern passes have vanished under ten metres of white. The summit villages are alone: nobody goes up, nobody comes down.",
                 "In the square of the highest village, a grey-haired woman plays a small drum. Each beat carries far, far away in the silence of the snow.",
                 "I'm Romanza. The last messenger, remember? I play so the other villages know we're still alive. They answer with another drum. If one day they don't answer, we'll know."],
           opts: ["“How many villages still answer?”", "Dig a way down with shovels", "“Teach the other villages a verse to ask for help.”"] },
      cuantos: { say: ["At the start of winter, eleven. Now, seven. The other four haven't answered for a month.",
                       "Maybe their drum broke. That's what I tell myself every morning."] },
      camino: { say: ["You dig with the summit folk for a week. Snow falls again at night and covers half of what you dug. In the end there's a narrow corridor, one body wide, down to the valley.",
                      "A corridor. To go down one at a time. Well. The old folk won't be able to use it. But the children will."] },
      verso: { say: ["A verse to ask for help? The Heights never asked. We carried everyone else's messages.",
                     "But she composes it. Four long beats, two short: “We're alive, we lack.” She plays it. From the other side of the mountain, after a while, someone repeats it.",
                     "They learnt it. Now the Heights know how to ask. It's strange. If the Heart calls, I'll go playing that: we're alive, we lack."] },
    } },
  });

  add("heart", {
    "e5-pareja": { who: { retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["In the Heart, the snow covers everything but the second statue. Around it, the ground is clear, as if the snow didn't dare touch it.",
                 "Two figures holding hands. One is ice, transparent, face raised. The other is a soft, porous stone, like a huge mushroom. Both have their mouths open. They're singing.",
                 "I'm Retama. Very old now. I've kept the Stump for fifty years. This statue is the only one that never changed. Not with the sap, not with the lake, not with the metal."],
           opts: ["“What does the base say?”", "Wipe the frost off the joined hands", "Sing the lullaby before the statue"] },
      base: { say: ["On the base there are carved letters, straight like the Deep's. Retama reads them slowly.",
                    "“Ice and Mushroom sang together, and from their song the first light was born. Let the two voices never again be parted.”",
                    "And below, in another hand, newer, scratched over it: “Let them never again come together.” Someone changed the law with a knife. And everyone reads the bottom line."] },
      limpiar: { say: ["With your sleeve you wipe the frost from the joined hands. Underneath, the two stone hands are warm. Not like the Stump, feverish: warm like a real hand.",
                       "Your creature sits between the two figures and closes its eyes."] },
      cantar: { say: ["You sing the lullaby before the statue. Your voice sounds alone in the snowy square. Halfway through you realise that a lullaby for two voices doesn't sound right with one.",
                      "It's missing the other voice. It always was. Ever since someone scratched the base."] },
    } },

    "e5-tumba": { who: { desvelo: "Desvelo, voice of Those Who Hear", cellisca: "Regent Cellisca" }, nodes: {
      a: { say: ["The Frozen Tomb lies at the heart of the Deep, but tonight everyone who matters stands before it. Regent Cellisca, with her crown. Desvelo, in his grey robe. Guards. Day folk who came down to ask and stayed to watch.",
                 "The Tomb's carved door has a new crack. Through the crack comes warm air, the only warm air in the Deep. And a sound, low, like someone turning over in bed.",
                 "The King wants to come out. It's the sign. We must open it and let him speak.",
                 "Or seal it forever. If people see what's inside, the regency is over. And if the regency is over, the granary opens, and the food is over."],
           opts: ["“What's really inside?”", "Open the Tomb again, in front of everyone", "Seal it, with Desvelo inside the crypt, as he asks", "Leave it as it is"] },
      adentro: { say: ["A root. The tip of an enormous root, on a slab. And the door scratched from the inside.",
                       "He knows. He always knew. And he tells people it's a king.",
                       "And you know it and rule in that king's name. Don't look at me as if I were the only one lying, regent."] },
      abrir: { say: ["You push the carved door. It opens with a creak of old ice. Inside, on a slab, the tip of an enormous root, grey, covered in frost. It beats, very slowly.",
                     "The Day folk come closer. They look. Nobody says anything for a long time.",
                     "Then someone asks: “And the King?” And another answers: “There never was one.” And the question runs down the line, outwards, all the way to the Meadow.",
                     "There. Now they know my crown is ice and nothing more. Tomorrow they'll want to open the granary too."] },
      sellar: { say: ["Inside. Yes. If the King won't speak, let someone speak from inside. Me. Forever. It's the only thing I know how to do: say what they need to hear.",
                      "Desvelo enters the Tomb with a lamp and a blanket. Cellisca watches him go in. The guards seal the door with water that freezes instantly.",
                      "From inside, after a while, his voice can be heard. Warm, slow. He speaks of the King. He speaks of waiting.",
                      "Now we have a King who speaks. Those Who Hear will get a temple out of this. Many generations from now, someone will pray to that door."] },
      dejar: { say: ["You do nothing. The crack stays open. The warm air keeps coming out. Desvelo keeps talking about the King. Cellisca keeps ruling in his name.",
                     "Well. So we go on. You chose too, Caretaker. Choosing not to choose is choosing too."] },
    } },

    "e5-final": { who: { cellisca: "Regent Cellisca", lirio: "Lirio, of the House of Ice", moho: "Moho, of the House of the Mushroom" }, nodes: {
      a: { say: ["The Deaf Root falls without a sound. Snow keeps falling on the Heart. Before the second statue, the one of two voices, stand Regent Cellisca, Lirio and Moho. Nobody knows how the three of them reached the same place.",
                 "The ancients sealed the Root's points with tombs. That was how they stopped what the Root couldn't stop alone. A new tomb here, and winter ends. The Deep's tablets say so.",
                 "And the law stays as it is. And us, each in our own House, forever.",
                 "There's something else. The statue says Ice and Mushroom sang together and a light was born. If we sing here, with everyone as witness... I don't know what happens. Nobody has done it in a thousand years.",
                 "And there's a third. Melt all the root ice. The whole granary. The stored cold gets loose and goes back to the Root, and the Root wakes. Spring. And hunger: the food rots in a week."],
           opts: ["“What happens if we seal a new tomb?”", "“And if we melt the root ice?”", "“And if Lirio and Moho sing together?”", "Seal a new point of the Root with a tomb", "Melt all the stored root ice", "Let Lirio and Moho sing together, with the nine as witnesses"] },
      q1: { say: ["Winter ends. The granary stays full, the regency stays standing, the law stays written. Everything in order.",
                  "Everything in order. Like in an ice box."] },
      q2: { say: ["The Root wakes. The Glade breathes. And the Deep loses everything it has: the ice, the food, the power. That spring people die of hunger. And the Deep won't forgive.",
                  "My House lives off that ice. My mother, my sisters. I don't know if I could look at them."] },
      q3: { say: ["I don't know. Nobody knows. If the statue tells the truth, something is born. A light. Like the first.",
                  "And if it tells the truth, there's this to think about too: the first light saw the pact. If another is born, there'll be two who saw it. And they won't remember the same thing.",
                  "And that only counts if the nine peoples are there. Without witnesses, it's a forbidden wedding and nothing more."] },
      tumba: { say: ["The Deep's cutters bring blocks of root ice. They build a small tomb over a crack in the Heart, where the Root shows through. Cellisca seals it with her own hand.",
                     "That night it stops snowing. For the first time in twenty years, the sky is clear. At dawn, an icicle drips in the Meadow.",
                     "It's over. Winter is over. And the regency ended it.",
                     "Lirio and Moho stand far apart. They don't look at each other. A week later, Lirio marries a young man of the Ice. Moho stops singing."] },
      deshielo: { say: ["You go down to the granary with Lirio, Moho and the cutters who want to help. They open the halls one by one. They break the walls of root ice with saws, with fire, with whatever there is.",
                        "Root ice melts for the first time in a thousand years. A cold wind comes out that rises through the whole Glade and sinks into the earth. Below, something enormous breathes.",
                        "The next day, the sun is warm. The snow melts in the Meadow. And in the granary, the food starts to smell.",
                        "Spring. There. Now the Deep has nothing. And the Glade is hungry. They'll hate me. You too."] },
      boda: { say: ["The nine arrive. The Meadow, packed tight, with blankets. Fire, with embers. The Forest, with the oak doors. The Court, with labelled blankets. The Tides, with rag flags. The Hondura, with the children. The Heights, with the drum. The Quarter, in line. The Deep, with Centeno counting.",
                    "Lirio and Moho stand before the second statue, hand in hand. They sing the lullaby. She with the straight voice of the Ice. He with the broken voice of the Mushroom. The two voices don't sound right together. Then they do.",
                    "Between the statue's two figures a light appears. Small, trembling. It grows. It rises. It stays in the air above the Heart: a new Star.",
                    "The law was broken in front of everyone. There's no way to write it again.",
                    "That night it stops snowing. Lirio and Moho look at the Star. She says the Star winked at her. He says no, it laughed. They no longer remember the same thing."] },
    } },
  });

  /* ==================== Delivery 2: the Day in winter (Meadow, Crater, Forest) ==================== */

  add("aurora", {
    "e5-velon": { who: { velon: "Velón, Lantern guard" }, nodes: {
      a: { say: ["Night falls on the Meadow. A Lantern guard, his cape white with frost, holds a skinny boy by the collar of his coat. The boy clutches two broken chairs as if they were a dog.",
                 "I'm Velón, Lantern guard. There's a cold curfew: after dark nobody walks the streets. This one took chairs from an empty house. To burn them.",
                 "The family from that house went to the Deep's queue a month ago. Maybe they'll come back. Maybe not. If they come back and have no chairs, it's my fault."],
           opts: ["“Why is there a cold curfew?”", "Let the boy go with the chairs", "“Take him to the guard post. There's a stove there.”", "Help the boy take the chairs back"] },
      toque: { say: ["Because at night people steal. Not out of malice: out of cold. First they steal chairs. Then doors. Then whole houses fall down because someone took the beams.",
                     "If the Meadow burns itself, when winter ends there won't be a Meadow. That's what they told me. I repeat it. Sometimes I believe it."] },
      soltar: { say: ["Velón looks at you, then at the boy. He lets go of the coat.",
                      "Go. Quick. I didn't see anything.",
                      "The boy runs through the snow with the chairs on his back. Two steps on he drops one. He doesn't come back for it.",
                      "A chair gives an hour's warmth. Well. Let it be a good hour."] },
      estufa: { say: ["The Lantern post is a hut with an iron stove. Velón sits the boy beside the fire. He burns one of the chairs, slowly, splinter by splinter.",
                      "The boy falls asleep sitting up. Velón covers him with his cape.",
                      "Tomorrow they'll ask me why I burnt a stolen chair in the Lantern stove. I'll say it was cold. It's true."] },
      devolver: { say: ["You take the chairs back with the boy. The empty house has a chalk mark on the door, in the Quarter's way: “We went to the Deep. We'll be back.”",
                        "The boy looks at the mark for a long time. Then he takes a piece of chalk from his pocket and writes underneath, in crooked letters: “I looked after your chairs.”",
                        "That doesn't warm anyone. But if they come back, they'll know someone passed by and took nothing."] },
    } },

    "e5-casasvacias": { who: { pavesa: "Pavesa, lamplighter" }, nodes: {
      a: { say: ["The Albors' street had the prettiest houses in the Meadow. Now half of them are empty. On every door, a chalk mark: “We went to the Deep.” Some have the date. The oldest are from two winters ago.",
                 "At the end of the street, a Quarter family sleeps in a doorway, in the snow, huddled against a closed door.",
                 "Pavesa again, the lantern one. That doorway belongs to an empty house. Inside there are beds. Outside, them. Nobody dares open it, because the marks say “we'll be back.”"],
           opts: ["“Has anyone ever come back?”", "Open the house for the family in the doorway", "Board up the empty houses so nobody loots them", "“Let the family in, but have them leave a new mark on the door.”"] },
      volvio: { say: ["One family. They came back without the grandfather and without the cow. They found the house with no doors. They left again.",
                      "Chalk marks are a promise. In winter, promises are worth as long as the chalk lasts."] },
      abrir: { say: ["You force the door with your shoulder. Inside it smells stale, of old soap. There are beds with blankets, a table, a stopped clock.",
                     "The family from the doorway walks in without a word. The mother touches the blankets as if they might bite her.",
                     "There. If the owners come back, there'll be a fight. But there'll be someone alive to fight."] },
      tapiar: { say: ["You nail boards over doors and windows, house by house, with Pavesa holding the nails. At the end of the street, the family in the doorway watches you work.",
                      "The houses will be whole when winter ends. Those who sleep outside, I don't know.",
                      "The next morning, the doorway is empty. Nobody knows where they went."] },
      marca: { say: ["The family goes in. First, the mother writes in chalk under the old mark: “We came in from the cold. We're looking after everything. If you come back, we'll leave you the middle bed.”",
                     "A mark under another mark. That's how it was done in the Quarter when there weren't enough squares. My grandfather would be pleased.",
                     "Within a week, half the empty houses on the street have two marks. On the corner one, someone added a third: “Thank you,” in a child's hand."] },
    } },

    "e5-mediosaco": { who: { ortiga: "Ortiga, of the Meadow" }, nodes: {
      a: { say: ["In the Meadow square, a broad-shouldered woman shares out what she brought from the Deep among five children sitting on a bench. She cuts the bread carefully, with a thread, so the pieces come out equal.",
                 "Ortiga's my name. Five children. I went down four days to the queue and they gave me this. You, the ones who decide, have you ever cut a loaf into five with a thread?"],
           opts: ["“Why did they give you so little?”", "“We shared it equally. It's little for everyone.”", "“Workers eat first. You have no work.”", "“Children first. Your children get a full share.”", "Give her what you're carrying", "“Gather the Meadow's mothers. Go to the Deep and talk.”"] },
      poco: { say: ["Because the Meadow doesn't cut ice or carry sacks or dig. The Meadow sows. And in winter there's nothing to sow. So the Meadow is worth nothing.",
                    "My grandmother used to say the Meadow fed the whole Glade. Now the Glade gives us the leftovers. I'll remember that. So will my children."] },
      igual: { say: ["Little for everyone. Yes. I know. The regent eats little too, they say.",
                     "They don't say the regent has one child and I have five. Equal isn't the same for everyone, Caretaker."] },
      trabajo: { say: ["Ortiga puts down the thread. She looks at you in a way you won't forget.",
                       "My husband cut wood. He died in the Forest last winter, cutting for the Crater. Now I have no work. Does that count?",
                       "Don't answer. I know what counts."] },
      ninos: { say: ["Yes. My children get a full share. That's why what I bring is for them and I haven't eaten since yesterday.",
                     "I'm not complaining. Well, I am. But I'd choose it again. That's what makes me angriest."] },
      dar: { say: ["You give her the bread and dried meat you had for the road. Ortiga looks at it without touching it.",
                   "And tomorrow? Will you bring bread tomorrow too? And for the other forty mothers in the square?",
                   "She takes it anyway. She cuts it into five with the thread. She doesn't eat."] },
      marcha: { say: ["Go to the Deep? To talk? To the regent?",
                      "She looks at the children. She looks at the square, where other mothers cut bread with thread.",
                      "Fine. But not to talk. To stand at the granary door with our children by the hand, all together, and make them look at us. Talking is for people with time.",
                      "A week later, eighty Meadow mothers go down to the Deep with their children. They stand at the granary door in silence. They ask for nothing. The queue behind lets them through.",
                      "Cellisca comes out on the third day. She gives each of them a sack. That night, in the Deep, the guard writes down the names of all eighty."] },
    } },

    "e5-tablero": { who: { pavesa: "Pavesa, lamplighter" }, nodes: {
      a: { say: ["Behind the square, under a metre of snow, Pavesa is digging with a wooden shovel. Underneath appears a stone wall covered in chalk squares, blurred by the damp.",
                 "My grandfather's board. The Quarter's nights, one per square. The snow covered it the first winter. I thought it had been wiped out.",
                 "Look at the last square. It's from the night before the first snowfall. After that, nothing. As if time had stopped here."],
           opts: ["“Why did he stop counting?”", "Start counting the days of winter on the board", "Wipe the board to start from scratch", "Carry the board to the square, where everyone can see it"] },
      porque: { say: ["My grandfather died that night. Of old age, in his bed, with the chalk in his hand. Not from the cold. It was chance.",
                      "Nobody kept counting because nobody wanted to be the one counting the winter. Counting is accepting that it lasts."] },
      contar: { say: ["You and Pavesa count the winters on your fingers, with the old folk, with the marks on the doors. In the end, she draws new squares. Lots of them. They fill the whole wall and carry on to the next.",
                      "By dusk there are seven thousand three hundred squares. Twenty years. Pavesa sits down in the snow and looks at them.",
                      "Now you can see it. Before it was one long night. Now it's seven thousand nights. It's worse. But it's true. Tomorrow I'll add one more."] },
      borrar: { say: ["Pavesa runs her hand over the wall. The old chalk comes apart like wet flour.",
                      "There. No missing nights and no extra nights. A clean wall.",
                      "The next day, someone has drawn a single square in the middle of the clean wall. Inside it says “today.”"] },
      plaza: { say: ["You cut out the piece of wall with the squares, stone by stone, and put it back together under the big lantern in the square. It takes three days.",
                     "People pass and look at it. An old woman looks for the square of the day she married. A child looks for the day he was born. Nobody finds today: it isn't there.",
                     "Tomorrow I'll add it. And the day after. And if winter ever ends, the last square will be drawn by whoever has the coldest hand."] },
    } },

    "e5-carbonilla": { who: { carbonilla: "Carbonilla, chimney sweep" }, nodes: {
      a: { say: ["Smoke rises from a chimney of the Albors' big house. It's the only chimney with smoke on the street. Down the roof comes a girl black with soot from head to toe.",
                 "Shh! My name's Carbonilla. I sweep chimneys, or I used to, when there were fires. This one has a fire every day. I went in to see why.",
                 "They have a cellar full of sacks with the Deep's seal. Granary sacks. Lots of them. And down in the queue they say there isn't enough."],
           opts: ["“How did they get those sacks?”", "Tell the whole street", "Take a few sacks at night and bring them to the square", "Knock on the door and talk to the Albors"] },
      como: { say: ["Bought. There's a Deep guard who sells sacks out the back door, for coins. The Albors have coins. They always have.",
                    "The regent says she doesn't know. Maybe she doesn't. Maybe she doesn't want to, because the guard's coins go up too."] },
      contar: { say: ["Carbonilla climbs a lantern post and shouts about the cellar to the whole street. People come out of their houses wrapped in blankets. They gather in front of the Albors' door.",
                      "Nobody breaks anything. They just stand there. After a while, old Albor opens the door, looks at the crowd and starts bringing out sacks. One per family.",
                      "He didn't do it out of goodness. He did it because there were a lot of us. We ate anyway. And now the whole Meadow knows the Deep sells out the back."] },
      sacar: { say: ["That night you go in with Carbonilla through the coal chute. You carry four sacks between you, in silence, and leave them in the square, under the lantern.",
                     "In the morning, four families eat. In the afternoon, the Albors put two guards on the door. Deep guards.",
                     "Four sacks. And now they have guards. Fine. Next time I'll go in by the chimney. That's what being skinny is for."] },
      hablar: { say: ["Old Albor opens the door himself. He wears a thick wool waistcoat and his cheeks are red from the heat. He listens to you without letting you in.",
                      "“I bought them with my own money. I didn't steal from anyone. If they were selling them, someone was going to buy them. Would you rather someone worse had?”",
                      "He shuts the door. Carbonilla, on the roof, makes a gesture that says she already knew."] },
    } },

    "e5-coplas": { who: { ortiga: "Ortiga, of the Meadow", velon: "Velón, Lantern guard" }, nodes: {
      a: { say: ["In the Meadow square, around the big lantern, a group is singing a new song. It's about an Ice girl and a Mushroom boy who love each other and aren't allowed. The words are funny. At the end, they aren't.",
                 "Ortiga, the one with the thread. Did you hear it? A carter brought it from the Deep. They say the Mushroom boy made it himself. Now the whole Meadow sings it.",
                 "Velón, of the Lantern. I got orders from the Deep: the song isn't to be sung. The regent says that song does more harm than the cold."],
           opts: ["“What harm does a song do?”", "Stand in front of the singers", "“Change the words. Don't name anyone.”", "Let the guard break them up"] },
      dano: { say: ["She says if people sing that one law is unfair, next they'll think all laws are unfair. And then the granary.",
                    "A song doesn't open granaries, Velón. Hunger does. The song only says what we already know."] },
      proteger: { say: ["You stand between Velón and the singers. You say nothing. Velón looks at you for a long time.",
                        "If I stay, I have to follow the order. If I leave, nobody follows it. I'll go and find another guard. I'm sure it'll take me a long time to find one.",
                        "Velón walks away slowly. The song goes on. Halfway through, Ortiga sings louder. At the end, for the last verses, the whole square is singing."] },
      cambiar: { say: ["No names? Fine. Let it be a girl from one house and a boy from another. Any houses.",
                       "The song changes. Now it doesn't speak of Ice or Mushroom. It speaks of any two houses and any law. Velón listens to the whole thing and finds nothing to forbid.",
                       "Like this I can't stop it. And like this anyone can sing it, about any law. I don't know if the regent won or lost."] },
      callar: { say: ["Velón strikes the lantern with his staff. People stop singing, one by one. They go home without looking at him.",
                      "Tomorrow I'll sing it at home. With the door shut. My five children know it.",
                      "I know. I followed the order. The order said nothing about houses."] },
    } },

    "e5-llamas": { who: { pavesa: "Pavesa, lamplighter" }, nodes: {
      a: { say: ["Pavesa is waiting for you at her house, with the door shut and the curtains drawn. On the table is a bowl with a frozen flame inside. The flame moves. Very little, like an eyelid.",
                 "Look. Last night my neighbour came to cry because her mother died in the queue. I took her hands. We both had the bowl between our hands without noticing.",
                 "The flame moved. It melted a little. It gave off heat. When I let go, it went still again. I tried it alone, with one hand, with both. Nothing. It has to be between two."],
           opts: ["“The flame I took from the lantern?”", "Try it with her, between both your hands", "“Tell the whole Meadow.”", "“Don't tell anyone yet. First we have to understand it.”"] },
      mia: { say: ["That one. The one that fell into your hand. I kept it. I owe you one.",
                   "You took it out of the glass. I kept it in a bowl. It took someone crying to make it move. I don't know what that means. Something, surely."] },
      probar: { say: ["You put your hands around the bowl, on the other side from Pavesa's. Her hands are cold and rough.",
                      "The flame trembles. It stretches. For a moment, the bowl is as warm as a cup of broth. Then Pavesa lets go and the flame goes still.",
                      "You see. Between two. The second statue in the Heart has two figures holding hands. My grandfather said they were singing. Maybe they were keeping warm too."] },
      contar: { say: ["Pavesa goes out to the square with the bowl. She passes it from pair to pair. With some pairs the flame doesn't move. With others it barely stirs.",
                      "With an old woman and a boy who don't know each other, the flame stretches all the way and warms the square for an instant. People clap as if it were a real fire.",
                      "It's not with just anyone. I don't know who it's with. But people take each other's hands to try. That's something, this winter."] },
      guardar: { say: ["You're right. If it gets out, the Deep will want the flames. Or the Court. And they'll sell them by the pair.",
                       "She wraps the bowl in a cloth and hides it in the cold oven.",
                       "When we know what it is, I'll tell. I hope we don't find out too late. Esporina, from the Mushroom, says truth that comes late is no use. That's what they say, anyway."] },
    } },

    "e5-ladrona": { who: { carbonilla: "Carbonilla, chimney sweep", velon: "Velón, Lantern guard" }, nodes: {
      a: { say: ["At the door of the Lantern post, Velón has a soot-blackened girl sitting on a bench, her wrists tied with ribbon. At her feet, a bucket of coal.",
                 "You! I'm Carbonilla, the chimney one. Tell him the coal was lying around. That nobody was using it.",
                 "Velón, of the Lantern. The coal was in the Lantern's coal store. It's for the posts' stoves. Without coal, the guards freeze. And without guards, there's more stealing."],
           opts: ["“Who was the coal for?”", "Pay for the coal so they let her go", "“Let her work at the post until it's paid off.”", "“The law is the law.”"] },
      quien: { say: ["For the Robles house, on the street below. They have a baby. The baby won't stop coughing.",
                     "There's always a baby. Sometimes it's true. This time it is, I went to look. That doesn't change whose coal it is."] },
      pagar: { say: ["You give Velón a few coins. He counts them, puts them away and cuts Carbonilla's ribbon.",
                     "Paid. Take the bucket. And next time, knock on the post door first. There's more coal than it looks.",
                     "Really? Fine. I'll knock. But if you don't open, I'm coming down the chimney."] },
      trabajar: { say: ["Work at the post? Her?",
                        "Carbonilla laughs. Then she sees it isn't a joke.",
                        "For a week, Carbonilla sweeps the chimneys of the Lantern posts. By the end, the stoves draw twice as well. Velón gives her a bucket of coal for every chimney.",
                        "She paid for the coal and took more. And my stoves don't smoke. I don't know who robbed whom."] },
      ley: { say: ["The law is the law. Yes. One night at the post, by the stove. Tomorrow she goes.",
                   "That night, Carbonilla sleeps beside the Lantern stove. It's her first warm night in a month. The bucket of coal stays at the post.",
                   "On the street below, the Robles baby coughs all night."] },
    } },
  });

  add("crater", {
    "e5-brasero": { who: { brasero: "Master Brasero, of the Guild" }, nodes: {
      a: { say: ["At the Crater's door, sitting on an iron chair beside a mountain of logs, a fat man in the Guild apron counts the wood that comes in. Each log, a line on a slate.",
                 "Master Brasero, of the Guild. You're the one from the Ford. Come to complain about the entry? Everyone comes to complain. Nobody comes to cut wood.",
                 "No logs, no fire. No fire, no Crater. I don't make winter's rules. I just write them down."],
           opts: ["“What happens to the leftover wood?”", "“The Guild sold warmth all its life. Now it charges at the door.”", "Cut wood to pay other people's entry", "“Tell me what the Crater was like before the winter.”"] },
      sobra: { say: ["Brasero stops writing. He looks at the mountain of logs, which is taller than the door.",
                     "There's none left over. It's stored. For when they don't bring any.",
                     "Fine. Some of it goes to the Hollow. The Court gives shadow blankets for wood. The masters use the blankets. What do you want? The masters get cold too."] },
      gremio: { say: ["All its life, yes. My grandfather sold furnaces. My father sold root metal. I sell a night by the fire.",
                      "What changes is what's sold. The Guild doesn't change. If it did, there'd be no Guild. And without the Guild, who looks after the fire? You?"] },
      cortar: { say: ["You go to the edge of the Forest with a borrowed axe and cut dead branches all day. You bring them on a sledge. Brasero counts them one by one, without letting a single one slide.",
                      "Twelve logs. Twelve nights. For whom?",
                      "You point to the people at the end of the queue. Brasero marks them on the slate, grudgingly.",
                      "Twelve. Not one more. Tomorrow, if you like, come back with the axe. It's the only complaint I accept."] },
      antes: { say: ["Before, there was smoke. Lots of it. And the noise of hammers. And metal was charged for, not entry. Nobody wanted to sleep here: it was the ugliest place in the Glade.",
                     "Now it's the loveliest. Because it's warm. What's lovely depends on how cold it is outside. Write that down, if you like. It's free."] },
    } },

    "e5-rescoldo": { who: { rescoldo: "Rescoldo, Chispa's grandson" }, nodes: {
      a: { say: ["At the bottom of the Crater, where the deep furnaces of the first forge used to be, someone has removed the stones covering the iron stairs. Down below, something red glows. A dry heat rises.",
                 "A young man with a pick climbs out of the hole, sweaty, red in the face. His hands are wrapped in rags.",
                 "I'm Rescoldo. My grandmother is Chispa. Don't tell her you saw me. Down there the root metal is still hot, like fifty years ago. If I bring it up, the whole Crater warms up. Nobody sleeps outside."],
           opts: ["“Do you know what the metal did to people's hands?”", "“Your grandmother forges cold. She knows why.”", "“Your grandmother has a whole grey hand.”", "“Your grandmother gave up forging because of it.”", "Help him dig", "Cover the hole with him", "Tell Chispa"] },
      manos: { say: ["Rescoldo looks at the rags on his hands.",
                     "I know. I wrap them. And I don't work it: I just bring it up. A little grey in exchange for nobody freezing. Look at the queue outside and tell me it's not worth it."] },
      abuelaA: { say: ["She forges cold and makes crooked nails. And we freeze with crooked nails.",
                       "I don't judge her. She chose her hands. I choose the queue outside."] },
      abuelaB: { say: ["Grey to the elbow. And she's the best smith there ever was. Everyone says so.",
                       "She taught me that metal is paid for with your hands. I'm paying. Same as her."] },
      abuelaC: { say: ["She gave it up, yes. She sells bread. And when she passes the Crater she doesn't look inside.",
                       "I don't want to give anything up. I want Fire to be good for something. That's what Fire is for."] },
      cavar: { say: ["You go down the iron stairs with Rescoldo. Down below, the air burns your eyes. Root metal pokes out of the rock like red veins.",
                     "You bring up three baskets in a day. You set them in the middle of the Crater. The heat reaches the door. That night the whole queue gets in.",
                     "In the morning, Rescoldo takes off the rags. There's a fine grey line along the edge of his nails.",
                     "It's started. Well. I knew."] },
      tapar: { say: ["Cover it? With the queue outside?",
                     "But he helps you. You put the stones back, one by one. The red glow disappears. The dry heat goes.",
                     "You chose for my hands. Thanks, I suppose. Tonight I'll sleep outside, with the queue. To see if I regret it."] },
      contar: { say: ["You find Chispa handing out embers. When you tell her, she sets the bucket down and stands very still.",
                      "She goes down to the bottom of the Crater slowly, with her cane. Rescoldo sees her coming and drops the pick.",
                      "She doesn't shout at him. The two of them sit at the edge of the hole, looking at the red below. They talk for an hour. When they come up, the hole is still open. Rescoldo has new rags, tightly tied, and Chispa is carrying the pick."] },
    } },

    "e5-dormidos": { who: { chispa: "Chispa, smith" }, nodes: {
      a: { say: ["Dawn in the Crater. People get up from the rows, fold their blankets, go out into the snow. In the last row, the farthest from the fire, an old man doesn't get up.",
                 "Chispa. Remember me? Help me with him. He's the third this week. Always in the last row.",
                 "The rows go by what you pay. Two logs, beside the fire. One, in the middle. Branches, at the back. Whoever brings branches sleeps at the edge, and the edge is almost outside."],
           opts: ["“Who decided the order?”", "“Let the rows rotate. Each night, one row closer.”", "“The old and the children by the fire. Whatever they pay.”", "Carry the old man out quietly"] },
      quien: { say: ["Nobody. It just happened. Whoever brought more lay down closer, and nobody told them no. Then the masters wrote it down. And what's written down is law.",
                     "That's how almost all laws are made, in the Guild. Someone puts themselves first and then it gets written."] },
      rotar: { say: ["That night, you and Chispa move people row by row. The two-log folk protest. The branch folk don't dare lie down near the fire.",
                     "Within a week, every family has slept one night beside the embers and one night at the edge. Nobody dies in the last row. Two fall ill in the first, from the heat and nerves.",
                     "Nobody's happy. Everybody's alive. That's what fair things are like, in my experience."] },
      necesidad: { say: ["And who decides who's old? Me? You?",
                         "You do it anyway. The old and the children in the middle, everyone else around them. Those who paid two logs sleep at the edge, furious.",
                         "Within a week, some young families stop bringing wood. Why bother, if they sleep far away anyway?",
                         "The old live. There's less wood. We'll see which weighs more. Nothing is free in the Crater. Not even kindness."] },
      sacar: { say: ["You wrap the old man in his blanket and carry him out with Chispa through the back door, so the children don't see. Outside, you lay him in the snow, beside two others.",
                     "The ground is too hard to bury them. They're waiting for spring. We're all waiting for spring.",
                     "Chispa goes back inside to hand out embers. She gives an extra handful to the last row."] },
    } },

    "e5-cizalla": { who: { cizalla: "Cizalla, buyer from outside" }, nodes: {
      a: { say: ["In a corner of the Crater, a very old woman in a fur cape nobody in the Glade knows how to tan is offering bread in exchange for something. The bread is white, from a wheat that doesn't grow here.",
                 "Cizalla. You know me. I came through the Hondura's tunnels, from the other side of the mountain. Over there winter is short. Nobody knows why here it doesn't end.",
                 "I bring wheat. Lots. I'll trade it for root metal. The red kind, that doesn't cool. Over there they pay well for it. What they use it for, I won't lie to you: swords."],
           opts: ["“What do they want swords for, on the other side?”", "“Rescoldo is bringing metal up from the bottom.”", "Trade metal for wheat", "“Take your wheat and don't come back.”", "“Wheat for something else. Blankets, wool, anything.”"] },
      espadas: { say: ["For the usual. There are three lords on the other side and each wants the other's valley. With root metal, a sword never notches. Whoever has more wins.",
                       "Don't look at me like that. You have a Root that looks after your valley. We have swords. Everyone makes do with what there is."] },
      rescoldo: { say: ["The grandson of the nail girl. Yes. I've already talked to him. He said he doesn't sell to outsiders.",
                        "He's young. Winter is long. He'll sell."] },
      cambiar: { say: ["You bring Cizalla a basket of red metal from the bottom of the Crater. She weighs it on a bone scale. She gives you ten sacks of white wheat.",
                       "That week, the Crater eats white bread. The children have never seen bread like it. Cizalla leaves through the tunnels with the basket on her back.",
                       "A good deal. For both of us. On the other side someone will win a war with your metal. You'll never know who. That's a good deal too."] },
      echar: { say: ["No wheat? With that queue outside?",
                     "She laughs, the dry laugh of an old woman. She loads the sacks onto her sledge.",
                     "I'll be back next moon. By then you'll have more hunger and less pride. It always happens."] },
      otra: { say: ["Blankets? We have sheep over there. Wool? We have wool.",
                    "She thinks for a while. She looks at the Crater's embers.",
                    "There's one thing. Songs. Over there we have no songs that put anyone to sleep. Sing me the lullaby, the Glade's, and I'll leave you two sacks. For my grandchildren, who don't sleep.",
                    "You sing her the lullaby. Cizalla repeats it three times, badly, until she gets it. She leaves you two sacks and goes off through the tunnels humming."] },
    } },

    "e5-voto": { who: { brasero: "Master Brasero, of the Guild", chispa: "Chispa, smith" }, nodes: {
      a: { say: ["In the Guild masters' hall, above the Crater, twelve masters sit in a half circle. In the middle, standing, Chispa. Brasero presides.",
                 "We vote on whether the Crater takes people without wood. Some say Fire doesn't charge those who have nothing. Some say without charging there's no Fire.",
                 "I say the first. You know that. That's why I'm standing."],
           opts: ["“Chispa already let them in. Did the fire go out?”", "Speak in favour of Chispa", "“Make the Court pay wood for the blankets it sells.”", "Stay out of the vote"] },
      apago: { say: ["No. It didn't go out. But we had to burn two Guild chairs. The chairs were my grandfather's.",
                     "Your grandfather's chairs warmed forty people, Brasero. Your grandfather would be proud. Or not. I didn't know him."] },
      chispa: { say: ["You speak before the twelve. You tell them about the last row, the old man who didn't get up, the bucket of embers. You don't raise your voice.",
                      "They vote. Six and six. Brasero has to decide. He scratches his beard for a long time.",
                      "Those without wood get in. But they carry water, sweep and stoke. Nobody sleeps free: whoever doesn't pay with logs pays with their hands. That way the others don't complain.",
                      "With hands. Fine. Fire understands that."] },
      corte: { say: ["The Court? Pay? The Court doesn't pay, it trades.",
                     "But he thinks about it. The masters murmur. The Court takes wood from the Crater to weave by the heat.",
                     "Fine. For every blanket the Court takes that was made with our wood, one free night for someone in the queue. I'll write it down. Let's see if the Court notices.",
                     "The Court notices. For a month, nobody from the Hollow comes asking for wood. Then they come back, and they pay."] },
      nada: { say: ["You stay at the back of the hall, silent. The masters vote. Seven to five: no wood, no entry.",
                    "Well. Seven to five. It used to be eleven to one. That's something.",
                    "Chispa leaves the hall with her head held high. Outside, in the queue, forty people without a log are waiting for her."] },
    } },

    "e5-molde": { who: { chispa: "Chispa, smith" }, nodes: {
      a: { say: ["At the bottom of the Crater, the old mould from the first casting lies on its side. It's so big that four families sleep inside it. Inside, the frost has filled the scratches of the names.",
                 "The list of those who worked the first forge. Forty-two. I scratched them with my nail as a girl, remember? Now, with the frost, you can read them all. Even the crossed-out one.",
                 "Under the line through the crossed-out name, the frost draws letters. And beside it, in another hand, very small: “went to the Ice.”",
                 "Nevado. It says Nevado."],
           opts: ["“Nevado? The one from the Watch?”", "Tell Esporina", "Scrape off the frost so it can't be read", "Copy the whole list onto a tablet"] },
      nevado: { say: ["The same. He worked the first forge as a young man, before the Ice. He left when he saw the grey hands. The masters crossed him out as a deserter.",
                      "Then he went to the Deep and looked after those who came from the Crater with grey hands. All his life. I never knew why. Now I do."] },
      esporina: { say: ["You go down to the Deep, to the Mushroom greenhouses. Esporina listens to you sitting among her mushrooms. When you say “went to the Ice,” she closes her eyes.",
                        "“He never told me he'd been Fire. A hundred and twenty years believing I knew everything about him. And I didn't know where he came from.”",
                        "“He left Fire because of the hands. He left me because of the law. He always left what hurt. I stayed. I don't know which of us was right.”"] },
      raspar: { say: ["Scrape it? Again?",
                      "But she lets you. You scrape off the frost with your sleeve. The crossed-out name becomes a line again. The families sleeping inside watch you without understanding.",
                      "There. A deserter again. Let him rest crossed out, if that's what he wanted."] },
      copiar: { say: ["You copy the forty-two names onto a tablet, with charcoal from an ember. The crossed-out one too, with the note beside it.",
                      "Chispa reads it aloud, name by name. Some of the families sleeping in the mould recognise a great-grandfather. A woman cries for a name she never knew.",
                      "Forty-two. Now they're in two places. If one is wiped out, the other stays. I learnt that from the Tides: always two copies."] },
    } },

    "e5-martillo": { who: { chispa: "Chispa, smith", rescoldo: "Rescoldo, Chispa's grandson" }, nodes: {
      a: { say: ["Chispa asks you to come to her house, on the south slope. It's a small house with a cold forge. On the cold anvil lies a hammer whose handle is worn by a single hand. Rescoldo sits in the doorway.",
                 "I don't have long, Caretaker. I can tell by how hard the slope is to climb. This hammer was the first thing Fire gave me. I want to decide where it goes.",
                 "I want it. I know what you're going to say, grandma. I want it anyway."],
           opts: ["“What do you want to happen to it?”", "“Give it to Rescoldo.”", "“Have it buried with you.”", "“Send it to the Ford. Let whoever comes use it.”"] },
      querer: { say: ["That nobody turns their hands grey with it. That's what I want. And that people keep striking. The two don't go together. They never did.",
                      "I turned my hands grey without a hammer, grandma. With a pick. The hammer changes nothing."] },
      rescoldo: { say: ["Chispa hands the hammer to Rescoldo. He takes it with both hands, as if it weighed more than it does.",
                        "Strike cold when you can. Red, when there's no other way. And count every time there was no other way. If there are many, you're doing something wrong.",
                        "I'll count. I promise. In chalk, like the Quarter folk."] },
      enterrar: { say: ["With me? Yes. I like it. Let the Fire I made go with me, and let Rescoldo make his own.",
                        "Grandma...",
                        "I know. It's not fair. You'll have to start from scratch. Like me, with a crooked nail. It's the best way I know."] },
      vado: { say: ["To the Ford? With you, who never grows old?",
                    "She laughs. A girl's laugh, the south slope girl's, from many years ago.",
                    "Fine. You keep it. When Rescoldo is old and knows what it costs, give it to him. If by then he still wants to strike, let him strike.",
                    "Rescoldo says nothing. He watches you take the hammer the way you watch something that will come back."] },
    } },

    "e5-grieta": { who: { brasero: "Master Brasero, of the Guild" }, nodes: {
      a: { say: ["A crack has opened in the Crater floor, end to end, right under the rows of sleepers. Warm, damp air comes out, smelling of earth. People fight to sleep on top of it.",
                 "Brasero. The crack appeared last night. It warms better than ten furnaces. And free. For the first time in my life, something gives warmth for free and I don't know how to charge for it.",
                 "You crouch down. The air coming out is warm as breath. Below, far below, something beats slowly. Those who slept on top have a grey line on their nails."],
           opts: ["“Why did it open here?”", "Cover the crack with snow and stones", "“Let them sleep on it. One night each.”", "Warn everyone about the nails"] },
      porque: { say: ["The old Guild folk say the Crater is where the Root has a fever. It always has. That's why we forge here.",
                      "If the Root is cooling everywhere, maybe it comes here to warm up. Like us. How funny."] },
      tapar: { say: ["You bring snow in buckets, stones, earth. People protest. Some lie down on the crack so you won't cover it.",
                     "In the end it's covered. The Crater's edges are cold again. Brasero sighs.",
                     "The nails are saved. The last row, I don't know. You decide what's lost, Caretaker. Always you."] },
      turnos: { say: ["You set up turns: each night, a different family sleeps on the crack. One night only. Brasero writes it on his slate, out of habit.",
                      "Within a month, half the Crater has a fine grey line on their nails. Nobody freezes.",
                      "A line. One night, one line. That's how you've always paid in the Crater. Now we all pay a little instead of some paying a lot."] },
      avisar: { say: ["You show people the nails of those who slept on it. Some move away from the crack. Others shrug and lie down.",
                      "A mother looks at her daughter's nails and moves her. An old man stays on top, hugging the warmth.",
                      "Now they know. Now everyone chooses. I can't charge for that either. This winter is ruining me."] },
    } },
  });

  add("forest", {
    "e5-serrin": { who: { serrin: "Serrín, woodcutter" }, nodes: {
      a: { say: ["At night, in the Deep Forest, an axe can be heard. Quick, nervous blows. Among the oaks, a young man with his face covered by a scarf is felling a young, healthy oak.",
                 "Don't shout! I'm Serrín. I know it's not allowed. But at the Crater a log is a night. And this oak is forty nights. My sisters sleep outside.",
                 "The Council doesn't cut. It says the oaks are roofs. The oaks aren't a roof for me. I don't have an oak."],
           opts: ["“How many oaks have you cut?”", "Take him before Abeto, of the Council", "“Cut dead branches. I'll show you which.”", "Buy his wood and give it away at the Crater"] },
      cuantos: { say: ["Six. This is the seventh. All young, because the old ones belong to families and the young ones belong to nobody.",
                       "The young ones were the three for one. The ones planted to replace. I know. I know, I know."] },
      abeto: { say: ["You take Serrín before Abeto. The Council man listens in silence, hands on his knees.",
                     "“The young oaks are the ones that will be roofs in ten years. You cut the roof of ten families that don't exist yet.”",
                     "The Council punishes him by making him plant ten acorns for every oak he cut, in the snow, where they don't grow. Serrín plants seventy. His sisters keep sleeping outside."] },
      muertas: { say: ["You show Serrín how to recognise a dead branch: no buds, grey, sounds hollow. You work together until dawn.",
                       "There's less wood than from an oak. Much less. But no tree falls.",
                       "Twelve nights. Not forty. Fine. My sisters sleep inside for twelve nights. Then I'll come back for branches. The Forest has lots of dead branches this winter."] },
      comprar: { say: ["You pay Serrín for the logs of the oak already felled. You load them onto a sledge and take them to the Crater. You hand them out at the door to those who have none.",
                       "You paid for an oak that was already dead. I don't know if you helped me or taught me that it sells.",
                       "A week later, an axe is heard again at night, farther away."] },
    } },

    "e5-avena": { who: { avena: "Old Avena, Centeno's mother" }, nodes: {
      a: { say: ["In a house at the foot of a hollow oak, a very thin woman knits a scarf beside a stove with no fire. Three children sleep in one bed, hugging each other.",
                 "Come in. I'm Avena, Centeno's mother. The one who hands out at the granary. My son is the most honest man in the Glade. Do you know him? He counts everything, down to the grains.",
                 "That's why we have no more than anyone else. He keeps nothing for himself. Others in his place would fill their cellars. Him, nothing."],
           opts: ["“Do you know about the sacks under the floor?”", "“Centeno gave everything back. That's why you're so thin.”", "“Centeno shared his among the families in the oaks.”", "“Your son keeps sacks under the floor.”", "“Your son is honest. You're right.”"] },
      piso: { say: ["Avena stops knitting. She looks at her hands.",
                    "Under the floor is what's there. I don't look at the floor. A mother doesn't look under her son's floor.",
                    "If she looks, she has to choose. And I don't want to choose between my son and someone else's grandchildren."] },
      devolvio: { say: ["Gave back? Gave what back?",
                        "You tell her. Avena listens with the half-knitted scarf on her knees.",
                        "So he had sacks. And he gave them back. For the others. While his nephews ate half.",
                        "She stays silent for a long while. Then she goes on knitting, faster.",
                        "He's honest. I told you. I don't know if it makes me glad."] },
      repartio: { say: ["Shared? Whose?",
                        "You tell her. The three sacks, the forty families, a handful each.",
                        "He stole it and gave it away. My son. He stole for everyone and gave us the same as the others. A handful.",
                        "I don't know if he's a saint or a fool. In my village, in winter, it's the same thing."] },
      guarda: { say: ["Avena looks at the floor. She looks at the old rug covering it. She doesn't get up.",
                      "I know. Since the first sack. That's why the children have cheeks like that.",
                      "I tell everyone he's honest so nobody looks under the rug. If you tell anyone, I won't forgive you. If you don't, I won't either. You know that already."] },
      honrado: { say: ["Yes. That's what I say.",
                       "She gives you the scarf, finished. It's grey, of rough wool, long.",
                       "For the cold on the road. Tell Centeno I knitted it, if you see him. Tell him to eat something. He always forgets to eat when he's handing out."] },
    } },

    "e5-madre": { who: { abeto: "Abeto, of the Council" }, nodes: {
      a: { say: ["The Forest Mother, the biggest tree in the Glade, is covered in ice up to the crown. From the old wounds in her bark hang icicles of dark sap, the colour of burnt honey.",
                 "Some children break the icicles with sticks and suck them. They say they're sweet. That they warm you inside.",
                 "Abeto, of the Council. The children come every day. They say with frozen sap they aren't cold. What they don't say is that night they dream black. All the same dream."],
           opts: ["“What do they dream?”", "“How is the Mother since they bled her?”", "“Is anything left of the Mother? Hacha said there was nothing left to cut.”", "Forbid them to eat the sap", "“Let them eat. One icicle per child, no more.”", "Gather the sap and take it to the House of the Mushroom"] },
      suenan: { say: ["A dark place, below, where something enormous is cold. The children say they hug it to warm it. That they wake with tired arms.",
                      "I don't know what it is. I know it's the Mother's sap. And that the Mother is connected to everything below."] },
      sangrada: { say: ["She bleeds little by little, as Hacha said. Three for one. Now, with the ice, the sap freezes as it comes out.",
                        "Hacha used to say the Mother gave us what we asked for, even if it hurt. It seems to me she now gives without being asked. That scares me more."] },
      nada: { say: ["Hacha was wrong. There's always something left. The Mother was left, because the Mother isn't cut, because she's the Mother.",
                    "Hacha sold the Court the stump wood. The Mother was left alone among stumps. That's why she weeps sap, the children say. Children say lots of things."] },
      prohibir: { say: ["Abeto puts a Council guard at the Mother's foot. The children stop coming by day. They come at night.",
                        "Forbidding is half of caring. I don't know what the other half is."] },
      racion: { say: ["One icicle per child, per day. Abeto hands them out himself, from a basket. The children queue. Nobody fights.",
                      "That night, all the Forest children dream the same dream, shorter. When they wake, they say the place below was a little less cold.",
                      "They hug something in their dreams, all together. And that something is less cold. I don't know if that's good for the children. For that thing below, it seems so."] },
      seta: { say: ["You gather the sap icicles in a basket and take them to the Deep, to the Mushroom greenhouses. Esporina looks at them with a wrinkled nose.",
                    "“The Mother's sap. This is eaten in dreams, not awake. The Mushroom knows about dreams. We'll keep it, study it. If it's good for anything, I'll tell you.”",
                    "She gives you back the empty basket. At the bottom there's a note: “Thank you. Don't bring any more.”"] },
    } },

    "e5-pelea": { who: { abeto: "Abeto, of the Council" }, nodes: {
      a: { say: ["Inside a hollow oak there's shouting. Two families, one from the Forest and one from the Meadow, are fighting over a corner by the fire. A pot lies on the floor.",
                 "Abeto again. Like this every day, in every oak. Those inside say the oak is theirs. Those from outside say the cold belongs to everyone.",
                 "The Council asks me for a rule. Just one, that works for every oak. I don't know how to make rules. I know how to hollow trees."],
           opts: ["“Do the outside families live in the oaks?”", "“A curtain in the middle. Each family, its half.”", "“One single rule: the fire in the centre, for everyone.”", "“Whoever fights spends a night in the snow.”"] },
      afuera: { say: ["In some. Where the Council opened the doors, yes. Where it didn't, they get in anyway, at night, and it's worse.",
                      "Opening isn't the hard part. The hard part is the day after, when they're already inside and nobody knows where to put the pot."] },
      cortina: { say: ["You hang a blanket from one side of the oak to the other. Each family, its half. Each one, its small fire.",
                       "They stop fighting. They don't talk either. From the other side of the blanket you hear coughing and nobody asks who.",
                       "Peace. Two small fires burn more wood than one big one. But peace."] },
      centro: { say: ["You put the fire in the centre of the oak. The two families sit around it, reluctantly, eyeing each other.",
                      "The first night, nobody talks. On the third, the Forest grandmother teaches the Meadow girl to knit. On the fifth, they share the pot.",
                      "One fire, one pot. I'll write it down. And if anyone fights, let them remember who taught them to knit."] },
      nieve: { say: ["Abeto announces it in every oak: whoever fights, a night in the snow. The first night, three men go out. One never comes back in: he goes to the Crater.",
                     "After that nobody fights. Nobody talks loudly either. In the oaks, people live in whispers.",
                     "It works. I don't like how. But it works."] },
    } },

    "e5-criaturas": { who: { serrin: "Serrín, woodcutter" }, nodes: {
      a: { say: ["In a Forest clearing, a pack of thin wild creatures surrounds a hollow oak. Their fur bristles with frost. They smell the food inside.",
                 "Serrín. They've come every night since winter began. They eat the oaks' bark. If they eat the bark, the oak dies, and the family inside has no roof.",
                 "People want to kill them. I have the axe. Nobody else dares."],
           opts: ["“Did they always come this far?”", "Feed them from the granary sacks", "Scare them off with fire", "Lead them to the Mushroom greenhouses"] },
      siempre: { say: ["No. Before, they stayed in the depths. But in the depths there's nothing green any more. The only green left is what people keep.",
                       "They're hungry like us. It's nobody's fault. That doesn't help, does it?"] },
      comer: { say: ["You open a granary sack in the snow. The creatures come closer slowly, wary. They eat everything. They leave nothing.",
                     "The next night, twice as many come back. And the next, three times as many.",
                     "We taught them there's food here. Now they'll never leave. And the sack belonged to a family."] },
      espantar: { say: ["You and Serrín light torches and run among the oaks shouting. The creatures flee into the depths of the Forest.",
                        "One, the thinnest, doesn't run fast. It falls in the snow. Serrín looks at it, axe in hand. He doesn't use it.",
                        "It'll die of cold anyway. But not because of me. It's strange, what you choose not to do."] },
      guiar: { say: ["With a sack of dried mushrooms, you open a path through the snow to the Mushroom tunnels, under the Deep. The creatures follow you, at a distance, all night.",
                     "In the greenhouses, Moho sees them arrive and roars with laughter. He gives them the stalks nobody eats. The creatures lie down in the damp warmth and fall asleep.",
                     "The Mushroom has room for everything nobody wants. That must be why it's loved so little."] },
    } },

    "e5-cuentas": { who: { abeto: "Abeto, of the Council" }, nodes: {
      a: { say: ["In the Council hall, inside the oldest oak, Abeto shows you an enormous book with bark pages. Each page is a year. Each line, one tree cut and three planted.",
                 "Abeto. The book of three for one. Since the rule was made. Every tree cut, three planted. It's all written down. Look at it closely.",
                 "You look. The lines are perfect, all the same. Too much the same. For the last twenty years, the handwriting never changes."],
           opts: ["“Who writes this?”", "“Hacha counted the living ones, one by one.”", "“Count out loud, before the whole Forest.”", "“Correct it quietly. From today, real numbers.”", "“Leave it as it is. Now isn't the time.”"] },
      quien: { say: ["Abeto closes the book slowly.",
                     "Me. For twenty years I've written three. One is planted. Sometimes none, because nothing grows in the snow. But I write three.",
                     "If I write one, the Council stops cutting. And if it stops cutting, the oaks don't get hollowed. And families freeze. The book lies so the Forest can live."] },
      hacha: { say: ["Hacha. Yes. She counted the living. Two of every three died on her, and she wrote it down. She cried as she wrote, they say.",
                     "Then she died and nobody wanted to cry while writing. Me neither. That's why I write three."] },
      publicar: { say: ["Abeto calls the whole Forest to the Council hall. He reads the book aloud, page by page. And then he says how many were really planted.",
                        "Silence. Then shouting. An old man throws an acorn in his face. A woman cries for an oak she thought was growing.",
                        "Now they know. The Forest will have fewer oaks than it thought. And from tomorrow, the book tells the truth. One line per living tree."] },
      corregir: { say: ["Abeto turns to a blank page. He writes the date. Below, in small letters: “From here, what there is.”",
                        "What's behind stays as it is. Nobody will read it. And if someone does, let them see where the handwriting changed.",
                        "On the next line, Abeto writes: “Cut: one. Planted: one. Alive: none.”"] },
      dejar: { say: ["Not now. Yes. It's never the time.",
                     "He puts the book away in a hollow of the oak. He runs his hand over the cover, the way you stroke an old dog.",
                     "When winter ends, I'll correct it. If it ends. If not, let whoever comes next correct it."] },
    } },

    "e5-semillas": { who: { avena: "Old Avena, Centeno's mother", abeto: "Abeto, of the Council" }, nodes: {
      a: { say: ["Avena is waiting for you at the door of the Council oak with a list in her hand, written in charcoal. Abeto stands beside her, worried.",
                 "Avena. The Forest's seeds are in the Deep's granary, under the root ice. All of them: acorns, pine cones, spring wheat. For when winter ends.",
                 "If the root ice ever melts, they'll rot with the food. And if they rot, there's no spring even if winter ends. Nobody thought of that."],
           opts: ["“Why did you keep them there?”", "Take the seeds out of the Deep and keep them in an oak", "“The granary is the safest place in the Glade.”", "“Half out, half in.”"] },
      porque: { say: ["Because root ice preserves everything. Seeds last a hundred years there. In an oak, they last as long as the damp allows.",
                      "And because my son hands out at the granary. We trust him. If we take the seeds out, people will ask why we don't trust him any more."] },
      sacar: { say: ["You go down to the Deep with Avena and a sledge. Centeno sees you coming and understands without being told. He opens the seed hall for you in silence.",
                     "You load bags of acorns, pine cones, wheat. Cellisca watches you pass from the corridor and says nothing. She writes something on a tablet.",
                     "You store them in the driest oak in the Forest, in clay jars sealed with wax.",
                     "Now they're ours. If they rot, it's our fault. I prefer that."] },
      dejar: { say: ["Yes. The safest. As long as nobody melts it.",
                     "And as long as the Deep wants to give them back. The Forest's seeds in the Deep's cellar. If I were the regent, I'd like that too.",
                     "Avena puts the list in her pocket. She doesn't throw it away."] },
      mitad: { say: ["You go down to the Deep and take out half. Centeno counts every bag twice, and writes “half” on his tablet.",
                     "Half stays under the root ice. The other half, in clay jars in a Forest oak.",
                     "If one half rots, the other is left. The Tides are right about the two copies. Even for acorns."] },
    } },
  });

})(window.EVEVENTS_EN);
